`timescale 1ns / 1ps
// Generated by pipeline/make_tasks.py (loop). Reference: golden/reference (asynch_comparator__ref below).
module tb;
  reg tb_clk; integer tb_seed, tb_cyc, tb_mis, tb_perr, tb_b, tb_k, tb_ph; reg tb_started; reg [31:0] tb_r;
  reg [2:0] rd_ptr;
  reg [2:0] wr_ptr;
  reg rd_dir;
  reg wr_dir;
  wire [0:0] full_ext; wire [0:0] ref_full_ext;
  wire [0:0] full_int; wire [0:0] ref_full_int;
  wire [0:0] empty; wire [0:0] ref_empty;
  asynch_comparator dut (.rd_ptr(rd_ptr), .wr_ptr(wr_ptr), .rd_dir(rd_dir), .wr_dir(wr_dir), .full_ext(full_ext), .full_int(full_int), .empty(empty));
  asynch_comparator__ref ref_i (.rd_ptr(rd_ptr), .wr_ptr(wr_ptr), .rd_dir(rd_dir), .wr_dir(wr_dir), .full_ext(ref_full_ext), .full_int(ref_full_int), .empty(ref_empty));
  always #5 tb_clk = ~tb_clk;
  function [31:0] tb_rand(input integer dummy); begin tb_rand = $random(tb_seed); end endfunction
  // flit: type in [30:29], VC in [28:27], destination row/column 0..3 in [7:4]/[3:0]
  function [31:0] tb_flit(input integer dummy); reg [31:0] r; begin r = $random(tb_seed);
    tb_flit = {1'b0, r[30:29], r[28:27], r[26:8], 2'b00, r[5:4], 2'b00, r[1:0]}; end endfunction
  task tb_prop(input [8*64:1] msg); begin tb_perr = tb_perr + 1;
    if (tb_perr <= 15) $display("FAIL property: %0s (t=%0t)", msg, $time); end endtask
  task tb_compare; begin
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1)
      if (ref_full_ext[tb_b] !== 1'bx && ref_full_ext[tb_b] !== 1'bz && full_ext[tb_b] !== ref_full_ext[tb_b]) begin
        tb_mis = tb_mis + 1; tb_b = 1;
        if (tb_mis <= 15) $display("FAIL t=%0t cycle %0d: full_ext = %h, expected %h", $time, tb_cyc, full_ext, ref_full_ext);
      end
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1)
      if (ref_full_int[tb_b] !== 1'bx && ref_full_int[tb_b] !== 1'bz && full_int[tb_b] !== ref_full_int[tb_b]) begin
        tb_mis = tb_mis + 1; tb_b = 1;
        if (tb_mis <= 15) $display("FAIL t=%0t cycle %0d: full_int = %h, expected %h", $time, tb_cyc, full_int, ref_full_int);
      end
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1)
      if (ref_empty[tb_b] !== 1'bx && ref_empty[tb_b] !== 1'bz && empty[tb_b] !== ref_empty[tb_b]) begin
        tb_mis = tb_mis + 1; tb_b = 1;
        if (tb_mis <= 15) $display("FAIL t=%0t cycle %0d: empty = %h, expected %h", $time, tb_cyc, empty, ref_empty);
      end
  end endtask
  task tb_props; begin
  end endtask
  reg [0:0] tbc_p_full_ext, tbc_t_full_ext;
  reg [0:0] tbc_p_full_int, tbc_t_full_int;
  reg [0:0] tbc_p_empty, tbc_t_empty;
  integer tbc_outs, tbc_bits;
  task tb_cov; begin
    if (tb_cyc > 6 || tb_ph == 1) tbc_t_full_ext = tbc_t_full_ext | ((ref_full_ext ^ tbc_p_full_ext) & ~(ref_full_ext ^ ref_full_ext)); tbc_p_full_ext = ref_full_ext;
    if (tb_cyc > 6 || tb_ph == 1) tbc_t_full_int = tbc_t_full_int | ((ref_full_int ^ tbc_p_full_int) & ~(ref_full_int ^ ref_full_int)); tbc_p_full_int = ref_full_int;
    if (tb_cyc > 6 || tb_ph == 1) tbc_t_empty = tbc_t_empty | ((ref_empty ^ tbc_p_empty) & ~(ref_empty ^ ref_empty)); tbc_p_empty = ref_empty;
  end endtask
  task tb_cov_report; begin tbc_outs = 0; tbc_bits = 0;
    if (|tbc_t_full_ext) tbc_outs = tbc_outs + 1;
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1) if (tbc_t_full_ext[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    if (|tbc_t_full_int) tbc_outs = tbc_outs + 1;
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1) if (tbc_t_full_int[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    if (|tbc_t_empty) tbc_outs = tbc_outs + 1;
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1) if (tbc_t_empty[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    $display("INFO coverage: %0d of 3 checked outputs toggled, %0d of 3 bits", tbc_outs, tbc_bits);
  end endtask
  initial begin
    tb_seed = 11; tb_clk = 0; tb_mis = 0; tb_perr = 0; tb_started = 0; tb_ph = 0; tb_k = 0;
    rd_ptr = 0; wr_ptr = 0; rd_dir = 0; wr_dir = 0;
    tbc_t_full_ext = 0; tbc_p_full_ext = 0; tbc_t_full_int = 0; tbc_p_full_int = 0; tbc_t_empty = 0; tbc_p_empty = 0;
    for (tb_cyc = 0; tb_cyc < 200; tb_cyc = tb_cyc + 1) begin
      @(negedge tb_clk);
      rd_ptr = {tb_rand(0)};
      wr_ptr = {tb_rand(0)};
      rd_dir = {tb_rand(0)};
      wr_dir = {tb_rand(0)};
      tb_started = (tb_cyc >= 6);
      #4 tb_ph = 0; tb_compare; tb_props; if (tb_started) tb_cov;
      @(posedge tb_clk); #4 tb_ph = 1; tb_compare; tb_props; if (tb_started) tb_cov;
    end
    tb_cov_report;
    if (tb_mis + tb_perr == 0) $display("ALL TESTS PASSED");
    else $display("FAIL: %0d mismatches, %0d property errors", tb_mis, tb_perr);
    $finish;
  end
endmodule

