module asynch_comparator__ref(rd_ptr, wr_ptr, rd_dir, wr_dir, full_ext, full_int, empty);

    input [2:0] rd_ptr;
    input [2:0] wr_ptr;
    input rd_dir;
    input wr_dir;
    output full_ext;
    output full_int;
    output empty;

	 reg full_int, empty ;
	 reg full_ext ;

	 
	 

	 always @ (rd_ptr or wr_ptr or rd_dir or wr_dir)
	 begin
	 
	 
	       
             if (((rd_ptr == wr_ptr) && (rd_dir != wr_dir)))
                 full_int=1;
             else full_int=0;
     
             if (((rd_ptr == wr_ptr) && (rd_dir == wr_dir)))
                 empty=1;
             else empty=0;
	 
	 
	 
	 
	 		if (rd_ptr == 3'b 000)
			begin
					if (wr_ptr == 3'b 000)	
					begin
						if (rd_dir != wr_dir)
							full_ext = 1'b 1 ;
						else
							full_ext = 1'b 0 ;
					end

					else if (wr_ptr == 3'b 001)
						 full_ext = 1'b 0 ;
					else if (wr_ptr == 3'b 011)
						 full_ext = 1'b 0 ;
					else if (wr_ptr == 3'b 010)
						 full_ext = 1'b 0 ;

				   else if (wr_ptr == 3'b 110)
						 full_ext = 1'b 1 ;
					else
						 full_ext = 1'b 1 ;
		   end

			else if (rd_ptr == 3'b 001)
			begin
					if (wr_ptr == 3'b 000)	
						 full_ext = 1'b 1 ;

					else if (wr_ptr == 3'b 001)
				   begin
						if (rd_dir != wr_dir)
							full_ext = 1'b 1 ;
						else
							full_ext = 1'b 0 ;
					end

					else if (wr_ptr == 3'b 011)
						 full_ext = 1'b 0 ;
					else if (wr_ptr == 3'b 010)
						 full_ext = 1'b 0 ;
				   else if (wr_ptr == 3'b 110)
						 full_ext = 1'b 0 ;

					else
						 full_ext = 1'b 1 ;
		   end

			else if (rd_ptr == 3'b 011)
			begin
					if (wr_ptr == 3'b 000)	
						 full_ext = 1'b 1 ;
					else if (wr_ptr == 3'b 001)
				   	 full_ext = 1'b 1 ;

					else if (wr_ptr == 3'b 011)
					begin
						if (rd_dir != wr_dir)
							full_ext = 1'b 1 ;
						else
							full_ext = 1'b 0 ;
					end 
						
					else if (wr_ptr == 3'b 010)
						 full_ext = 1'b 0 ;
				   else if (wr_ptr == 3'b 110)
						 full_ext = 1'b 0 ;
					else
						 full_ext = 1'b 0 ;
		   end

			else if (rd_ptr == 3'b 010)
			begin
					if (wr_ptr == 3'b 000)	
						 full_ext = 1'b 0 ;

					else if (wr_ptr == 3'b 001)
				   	 full_ext = 1'b 1 ; 
					else if (wr_ptr == 3'b 011)
						 full_ext = 1'b 1 ;
						
					else if (wr_ptr == 3'b 010)
					begin
						if (rd_dir != wr_dir)
							full_ext = 1'b 1 ;
						else
							full_ext = 1'b 0 ;
					end
				  						
				   else if (wr_ptr == 3'b 110)
						 full_ext = 1'b 0 ;	
					else
						 full_ext = 1'b 0 ;
		   end 

			else if (rd_ptr == 3'b 110)
			begin
					if (wr_ptr == 3'b 000)	
						 full_ext = 1'b 0 ; 
					else if (wr_ptr == 3'b 001)
				   	 full_ext = 1'b 0 ; 

					else if (wr_ptr == 3'b 011)
						 full_ext = 1'b 1 ;
					else if (wr_ptr == 3'b 010)
						 full_ext = 1'b 1 ;
				  						
				   else if (wr_ptr == 3'b 110)
					begin
						if (rd_dir != wr_dir)
							full_ext = 1'b 1 ;
						else
							full_ext = 1'b 0 ;
					end	 
						 
				 	else
						 full_ext = 1'b 0 ;
		   end 

			else		 
			begin 
			     if (wr_ptr == 3'b 000)	
						 full_ext = 1'b 0 ; 
					else if (wr_ptr == 3'b 001)
				   	 full_ext = 1'b 0 ; 
					else if (wr_ptr == 3'b 011)
						 full_ext = 1'b 0 ;

					else if (wr_ptr == 3'b 010)
						 full_ext = 1'b 1 ; 				  						
				   else if (wr_ptr == 3'b 110)
						 full_ext = 1'b 1 ;
						 
				 	else
					begin
						if (rd_dir != wr_dir)
							full_ext = 1'b 1 ;
						else
							full_ext = 1'b 0 ;
					end	 
		   end 
	 end 
endmodule
